from AlgorithmImports import *

class MultiStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for t in tickers:
            self.symbols[t] = self.AddEquity(t, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        # Slot 1 - Strategy A indicators
        self.spy_sma = self.SMA(self.spy, 50, Resolution.Daily)
        self.prev_spy_close = None
        self.prev_spy_sma = None
        self.strategyA_shares = 0

        # Slot 2 - Strategy B indicators
        self.aapl_rsi = self.RSI(self.aapl, 14, Resolution.Daily)
        self.prev_aapl_close = None
        self.aapl_red_streak = 0
        self.strategyB_shares = 0

        self.warmupBars = 0
        self.requiredWarmup = 51  # need prev SMA + current SMA formed, and enough history

    def OnData(self, slice):
        # Skip if any subscribed ticker's bar is missing today
        for sym in self.symbols.values():
            if not slice.ContainsKey(sym) or slice[sym] is None:
                return

        spy_close = slice[self.spy].Close
        aapl_close = slice[self.aapl].Close

        # Update AAPL red streak (market-state, computed continuously)
        if self.prev_aapl_close is not None:
            if aapl_close < self.prev_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        # ---------------- Slot 1: Strategy A (SPY) ----------------
        if self.spy_sma.IsReady and self.prev_spy_close is not None and self.prev_spy_sma is not None:
            crossed_below = (self.prev_spy_close <= self.prev_spy_sma) is False and \
                             (self.prev_spy_close >= self.prev_spy_sma) and spy_close < self.spy_sma.Current.Value
            # Correct cross-below: yesterday close >= yesterday sma, today close < today sma
            crossed_below = (self.prev_spy_close >= self.prev_spy_sma) and (spy_close < self.spy_sma.Current.Value)
            # Correct cross-above: yesterday close <= yesterday sma, today close > today sma
            crossed_above = (self.prev_spy_close <= self.prev_spy_sma) and (spy_close > self.spy_sma.Current.Value)

            if self.strategyA_shares > 0:
                # Sell reason only while lot non-empty
                if crossed_below:
                    self.MarketOrder(self.spy, -self.strategyA_shares)
                    self.strategyA_shares = 0
            else:
                # Buy reason only while lot empty
                if crossed_above:
                    target_value = 0.40 * self.Portfolio.TotalPortfolioValue
                    qty = int(target_value // spy_close)
                    if qty > 0:
                        self.MarketOrder(self.spy, qty)
                        self.strategyA_shares = qty

        # ---------------- Slot 2: Strategy B (AAPL) ----------------
        if self.aapl_rsi.IsReady and self.prev_aapl_close is not None:
            if self.strategyB_shares > 0:
                # Sell reason only while lot non-empty
                if self.aapl_rsi.Current.Value > 60:
                    self.MarketOrder(self.aapl, -self.strategyB_shares)
                    self.strategyB_shares = 0
            else:
                # Buy reason only while lot empty
                if self.aapl_red_streak >= 3:
                    cost = 20000.0
                    if self.Portfolio.Cash >= cost:
                        qty = int(cost // aapl_close)
                        if qty > 0:
                            self.MarketOrder(self.aapl, qty)
                            self.strategyB_shares = qty
                    # otherwise do nothing this bar; reason may fire again later

        # Update previous-value state for next bar
        self.prev_spy_close = spy_close
        if self.spy_sma.IsReady:
            self.prev_spy_sma = self.spy_sma.Current.Value
        self.prev_aapl_close = aapl_close

