        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.sma_spy = self.SMA(self.spy, 100, Resolution.Daily)
        self.rsi_aapl = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        # Strategy A state (SPY)
        self.a_lot_shares = 0
        self.prev_spy_close = None
        self.prev_spy_sma = None

        # Strategy B state (AAPL)
        self.b_lot_shares = 0
        self.prev_aapl_close = None
        self.aapl_red_streak = 0

    def OnData(self, data: Slice):
        # Skip day entirely if any subscribed ticker's bar is missing
        for sym in self.symbols:
            if not data.ContainsKey(sym) or data[sym] is None:
                return

        spy_close = data[self.spy].Close
        aapl_close = data[self.aapl].Close

        # Update AAPL red-day streak using today's vs previous day's close
        if self.prev_aapl_close is not None:
            if aapl_close < self.prev_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        # Ensure indicators are ready before evaluating rules
        sma_ready = self.sma_spy.IsReady
        rsi_ready = self.rsi_aapl.IsReady

        # ---------- Strategy A (SPY) ----------
        if sma_ready:
            sma_val = self.sma_spy.Current.Value

