            cross_above = False
            if self.prev_spy_close is not None and self.prev_spy_sma is not None:
                if self.prev_spy_close <= self.prev_spy_sma and spy_close > sma_val:
                    cross_above = True
                if self.prev_spy_close >= self.prev_spy_sma and spy_close < sma_val:
