                    target_value = 0.40 * self.Portfolio.TotalPortfolioValue
                    shares = int(target_value / spy_close)
                    if shares > 0:
                        self.MarketOrder(self.spy, shares)
                        self.a_lot_shares = shares

            self.prev_spy_close = spy_close
            self.prev_spy_sma = sma_val
        else:
            self.prev_spy_close = spy_close
            # sma not ready, no sma value to store

        # ---------- Strategy B (AAPL) ----------
        # Sell before buy
        if self.b_lot_shares > 0:
            if rsi_ready and self.rsi_aapl.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.b_lot_shares)
                self.b_lot_shares = 0
        elif self.b_lot_shares == 0:
            if self.aapl_red_streak >= 3:
                cost = 20000.0
                if self.Portfolio.Cash >= cost:
                    shares = math.floor(cost / aapl_close)
                    if shares > 0:
                        self.MarketOrder(self.aapl, shares)
                        self.b_lot_shares = shares

        self.prev_aapl_close = aapl_close

