        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for t in tickers:
            self.symbols[t] = self.AddEquity(t, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        # Indicators
        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.aapl, 14, Resolution.Daily, MovingAverageType.Wilders)

        # Cross-tracking state for Strategy A (SPY vs its 100-day SMA)
        self.prev_spy_close = None
        self.prev_spy_sma = None

        # Red-streak tracking state for Strategy B (AAPL)
        self.prev_aapl_close = None
        self.aapl_red_streak = 0

        # Private lots
        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data: Slice):
        # Skip the whole day if any subscribed ticker's bar is missing.
        for sym in self.symbols.values():
            if not data.Bars.ContainsKey(sym):
                return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        # --- Update AAPL red-streak state (computed continuously) ---
        if self.prev_aapl_close is not None:
            if aapl_close < self.prev_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        # ================= Strategy A: SPY vs 100-day SMA =================
        if self.spy_sma.IsReady:
            spy_sma_val = self.spy_sma.Current.Value

            if self.prev_spy_close is not None and self.prev_spy_sma is not None:
                crossed_above = (self.prev_spy_close <= self.prev_spy_sma) and (spy_close > spy_sma_val)
                crossed_below = (self.prev_spy_close >= self.prev_spy_sma) and (spy_close < spy_sma_val)

                # Evaluate sells before buys.
                if self.spy_lot > 0:
                    if crossed_below:
                        self.MarketOrder(self.spy, -self.spy_lot)
                        self.spy_lot = 0
                else:
                    if crossed_above:
                        target_value = 0.4 * self.Portfolio.TotalPortfolioValue
                        shares = int(math.floor(target_value / spy_close))
                        if shares > 0:
                            self.MarketOrder(self.spy, shares)
                            self.spy_lot += shares

            self.prev_spy_sma = spy_sma_val
            self.prev_spy_close = spy_close
        else:
            self.prev_spy_close = spy_close

        # ================= Strategy B: AAPL red-streak / RSI =================
        # Sell reason requires the RSI(14) to be fully formed.
        if self.aapl_lot > 0:
            if self.aapl_rsi.IsReady:
                if self.aapl_rsi.Current.Value > 60:
                    self.MarketOrder(self.aapl, -self.aapl_lot)
                    self.aapl_lot = 0
        else:
            # Buy reason only needs 3 consecutive red days of close history.
            if self.aapl_red_streak >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares = int(math.floor(20000 / aapl_close))
                    if shares > 0:
                        self.MarketOrder(self.aapl, shares)
                        self.aapl_lot += shares

        self.prev_aapl_close = aapl_close

