        for t in tickers:
            equity = self.AddEquity(t, Resolution.Daily)
            self.symbols[t] = equity.Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        # Indicators
        self.sma100 = self.SMA(self.spy, 100, Resolution.Daily)
        self.rsi14 = self.RelativeStrengthIndex(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        # Rolling window of previous closes for red-day streak tracking (AAPL)
        self.aapl_close_window = RollingWindow[float](2)

        # Previous day's SMA/close for cross detection (Strategy A)
        self.prev_spy_close = None
        self.prev_sma = None

        # Strategy lot tracking
        self.lotA_shares = 0
        self.lotB_shares = 0

        # AAPL consecutive red day counter
        self.aapl_red_streak = 0
        self.prev_aapl_close = None

        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data: Slice):
        # Skip all rule evaluation if any subscribed ticker's bar is missing today
        for sym in self.symbols.values():
            if not data.ContainsKey(sym) or data[sym] is None:
                return

        if self.IsWarmingUp:
            return

        if not self.sma100.IsReady or not self.rsi14.IsReady:
            return

        spy_close = data[self.spy].Close
        aapl_close = data[self.aapl].Close
        sma_value = self.sma100.Current.Value

        # ---- Update AAPL consecutive red-day streak ----
        if self.prev_aapl_close is not None:
            if aapl_close < self.prev_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        # ---- Determine crosses for Strategy A (SPY vs its 100-day SMA) ----
        cross_above = False
        cross_below = False
        if self.prev_spy_close is not None and self.prev_sma is not None:
            if self.prev_spy_close <= self.prev_sma and spy_close > sma_value:
                cross_above = True
            if self.prev_spy_close >= self.prev_sma and spy_close < sma_value:
                cross_below = True

        # ================= Strategy A (SPY) =================
        # Sell before buy
        if self.lotA_shares > 0:
            if cross_below:
                self.MarketOrder(self.spy, -self.lotA_shares)
                self.lotA_shares = 0
        else:
            if cross_above:
                total_value = self.Portfolio.TotalPortfolioValue
                target_value = 0.40 * total_value
                shares = int(target_value // spy_close)
                if shares > 0:
                    self.MarketOrder(self.spy, shares)
                    self.lotA_shares += shares

        # ================= Strategy B (AAPL) =================
        # Sell before buy
        if self.lotB_shares > 0:
            if self.rsi14.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.lotB_shares)
                self.lotB_shares = 0
        else:
            if self.aapl_red_streak >= 3:
                cash_needed = 20000.0
                if self.Portfolio.Cash >= cash_needed:
                    shares = int(cash_needed // aapl_close)
                    if shares > 0:
                        self.MarketOrder(self.aapl, shares)
                        self.lotB_shares += shares

        # ---- Update state for next bar ----
        self.prev_spy_close = spy_close
        self.prev_sma = sma_value
        self.prev_aapl_close = aapl_close
